import json
import urllib.parse
import urllib.request

BASE = "http://prices.internal/api/v1/price"


def get_price(sku: str) -> float:
    """Fetch the current price for *sku* from the internal pricing service."""
    url = f"{BASE}/{urllib.parse.quote(sku, safe='')}"
    with urllib.request.urlopen(url, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list[str]) -> float:
    return sum(map(get_price, skus))
